drop policy if exists "school managers write module records" on public.schoolpro_module_records;
create policy "school managers write module records" on public.schoolpro_module_records
for all to authenticated
using (
 exists(select 1 from public.schoolpro_schools s where s.id=schoolpro_module_records.school_id and s.owner_id=auth.uid())
 or exists(select 1 from public.schoolpro_members m where m.school_id=schoolpro_module_records.school_id and m.user_id=auth.uid() and m.role='administrator'::public.school_member_role)
 or exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='super_admin'::public.user_role)
 or (
   module=any(array['assignments','cbt','timetable','announcements'])
   and exists(select 1 from public.schoolpro_members m where m.school_id=schoolpro_module_records.school_id and m.user_id=auth.uid() and m.role='teacher'::public.school_member_role)
 )
)
with check (
 exists(select 1 from public.schoolpro_schools s where s.id=schoolpro_module_records.school_id and s.owner_id=auth.uid())
 or exists(select 1 from public.schoolpro_members m where m.school_id=schoolpro_module_records.school_id and m.user_id=auth.uid() and m.role='administrator'::public.school_member_role)
 or exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='super_admin'::public.user_role)
 or (
   module=any(array['assignments','cbt','timetable','announcements'])
   and exists(select 1 from public.schoolpro_members m where m.school_id=schoolpro_module_records.school_id and m.user_id=auth.uid() and m.role='teacher'::public.school_member_role)
 )
);

