-- Leave: own member can create/read own request; management/HR can manage school requests.
drop policy if exists "school member access schoolpro_leave_requests" on public.schoolpro_leave_requests;
drop policy if exists "schoolpro_module_permission" on public.schoolpro_leave_requests;
create policy "leave own read" on public.schoolpro_leave_requests for select to authenticated
using (private.schoolpro_module_allowed(school_id,'leave') and exists(select 1 from public.schoolpro_members m where m.id=member_id and m.school_id=schoolpro_leave_requests.school_id and m.user_id=auth.uid()));
create policy "leave own request" on public.schoolpro_leave_requests for insert to authenticated
with check (private.schoolpro_module_allowed(school_id,'leave') and status='pending' and exists(select 1 from public.schoolpro_members m where m.id=member_id and m.school_id=schoolpro_leave_requests.school_id and m.user_id=auth.uid()));
create policy "leave management access" on public.schoolpro_leave_requests for all to authenticated
using (private.schoolpro_module_allowed(school_id,'leave') and private.has_school_access(school_id,array['proprietor','administrator','hr_officer']::public.school_member_role[]))
with check (private.schoolpro_module_allowed(school_id,'leave') and private.has_school_access(school_id,array['proprietor','administrator','hr_officer']::public.school_member_role[]));

