create policy "lesson notes leadership access" on public.schoolpro_lesson_notes for all to authenticated
using (private.schoolpro_module_allowed(school_id,'lesson-notes') and private.has_school_access(school_id,array['proprietor','administrator','head_teacher','vice_principal']::public.school_member_role[]))
