create policy "calendar school read" on public.schoolpro_calendar_events for select to authenticated
using (private.schoolpro_module_allowed(school_id,'calendar') and exists(select 1 from public.schoolpro_members m where m.school_id=schoolpro_calendar_events.school_id and m.user_id=auth.uid()));
create policy "calendar management write" on public.schoolpro_calendar_events for all to authenticated
using (private.schoolpro_module_allowed(school_id,'calendar') and private.has_school_access(school_id,array['proprietor','administrator','head_teacher','vice_principal','registrar']::public.school_member_role[]))
