drop policy if exists "teacher assignments" on public.schoolpro_assignments;
create policy "assignment staff manage" on public.schoolpro_assignments for all to authenticated
using (private.schoolpro_module_allowed(school_id,'assignments') and private.has_school_access(school_id,array['proprietor','administrator','head_teacher','vice_principal','teacher','class_teacher']::public.school_member_role[]))
with check (private.schoolpro_module_allowed(school_id,'assignments') and private.has_school_access(school_id,array['proprietor','administrator','head_teacher','vice_principal','teacher','class_teacher']::public.school_member_role[]));

-- Assignment submissions: students read own only; academic staff may manage within school.
drop policy if exists "submission access" on public.schoolpro_assignment_submissions;
create policy "assignment submission student read own" on public.schoolpro_assignment_submissions for select to authenticated
using (exists(select 1 from public.schoolpro_students s where s.id=student_id and s.user_id=auth.uid()));
create policy "assignment submission staff manage" on public.schoolpro_assignment_submissions for all to authenticated
using (exists(select 1 from public.schoolpro_assignments a where a.id=assignment_id and private.schoolpro_module_allowed(a.school_id,'assignments') and private.has_school_access(a.school_id,array['proprietor','administrator','head_teacher','vice_principal','teacher','class_teacher']::public.school_member_role[])))
with check (exists(select 1 from public.schoolpro_assignments a where a.id=assignment_id and private.schoolpro_module_allowed(a.school_id,'assignments') and private.has_school_access(a.school_id,array['proprietor','administrator','head_teacher','vice_principal','teacher','class_teacher']::public.school_member_role[])));

-- CBT attempts: students read own; management/exam roles read/manage. Student mutations remain RPC-only.
drop policy if exists "attempt school access" on public.schoolpro_cbt_attempts;
create policy "cbt attempt student read own" on public.schoolpro_cbt_attempts for select to authenticated
using (exists(select 1 from public.schoolpro_students s where s.id=student_id and s.user_id=auth.uid()));
create policy "cbt attempt staff manage" on public.schoolpro_cbt_attempts for all to authenticated
using (exists(select 1 from public.schoolpro_cbt_tests t where t.id=test_id and private.schoolpro_module_allowed(t.school_id,'cbt') and public.schoolpro_can_manage_cbt(t.school_id)))
with check (exists(select 1 from public.schoolpro_cbt_tests t where t.id=test_id and private.schoolpro_module_allowed(t.school_id,'cbt') and public.schoolpro_can_manage_cbt(t.school_id)));

-- CBT answers: students read their own answers; writes are through save/submit RPCs.
drop policy if exists "answer attempt access" on public.schoolpro_cbt_answers;
create policy "cbt answer student read own" on public.schoolpro_cbt_answers for select to authenticated
using (exists(select 1 from public.schoolpro_cbt_attempts a join public.schoolpro_students s on s.id=a.student_id where a.id=attempt_id and s.user_id=auth.uid()));
create policy "cbt answer staff manage" on public.schoolpro_cbt_answers for all to authenticated
using (exists(select 1 from public.schoolpro_cbt_attempts a join public.schoolpro_cbt_tests t on t.id=a.test_id where a.id=attempt_id and private.schoolpro_module_allowed(t.school_id,'cbt') and public.schoolpro_can_manage_cbt(t.school_id)))
with check (exists(select 1 from public.schoolpro_cbt_attempts a join public.schoolpro_cbt_tests t on t.id=a.test_id where a.id=attempt_id and private.schoolpro_module_allowed(t.school_id,'cbt') and public.schoolpro_can_manage_cbt(t.school_id)));

drop policy if exists "school question read" on public.schoolpro_question_bank;
create policy "question bank authorized read" on public.schoolpro_question_bank
for select to authenticated
using (
 private.schoolpro_module_allowed(school_id,'cbt')
 and public.schoolpro_can_manage_cbt(school_id)
);

drop policy if exists "test question school read" on public.schoolpro_cbt_test_questions;
create policy "test question authorized read" on public.schoolpro_cbt_test_questions
for select to authenticated
using (
 exists(
   select 1 from public.schoolpro_cbt_tests t
   where t.id=schoolpro_cbt_test_questions.test_id
     and private.schoolpro_module_allowed(t.school_id,'cbt')
     and public.schoolpro_can_manage_cbt(t.school_id)
 )
);

-- Anonymous clients do not need direct table privileges; candidate exams use controlled SECURITY DEFINER RPCs.
revoke all on table public.schoolpro_question_bank from anon;
revoke all on table public.schoolpro_cbt_test_questions from anon;
revoke all on table public.schoolpro_cbt_tests from anon;

create or replace function public.schoolpro_can_author_cbt(p_school uuid)
returns boolean language sql stable security definer set search_path='' as $$
 select private.is_admin(array['super_admin']::public.user_role[])
 or exists(select 1 from public.schoolpro_schools s where s.id=p_school and s.owner_id=auth.uid())
 or exists(select 1 from public.schoolpro_members m where m.school_id=p_school and m.user_id=auth.uid()
   and m.role::text in('proprietor','administrator','teacher','class_teacher','exam_officer','head_teacher','vice_principal'))
$$;

create or replace function public.schoolpro_can_manage_cbt(p_school uuid)
returns boolean language sql stable security definer set search_path='' as $$
 select private.is_admin(array['super_admin']::public.user_role[])
 or exists(select 1 from public.schoolpro_schools s where s.id=p_school and s.owner_id=auth.uid())
 or exists(select 1 from public.schoolpro_members m where m.school_id=p_school and m.user_id=auth.uid()
   and m.role::text in('proprietor','administrator','exam_officer','head_teacher','vice_principal'))
$$;

revoke all on function public.schoolpro_can_author_cbt(uuid) from public,anon;
grant execute on function public.schoolpro_can_author_cbt(uuid) to authenticated,service_role;

-- Content authoring remains available to teachers/class teachers.
drop policy if exists "question bank authorized read" on public.schoolpro_question_bank;
create policy "question bank authorized read" on public.schoolpro_question_bank for select to authenticated
using (private.schoolpro_module_allowed(school_id,'cbt') and public.schoolpro_can_author_cbt(school_id));
drop policy if exists "school question manage" on public.schoolpro_question_bank;
create policy "school question manage" on public.schoolpro_question_bank for all to authenticated
using (private.schoolpro_module_allowed(school_id,'cbt') and public.schoolpro_can_author_cbt(school_id))
with check (private.schoolpro_module_allowed(school_id,'cbt') and public.schoolpro_can_author_cbt(school_id));

drop policy if exists "test question authorized read" on public.schoolpro_cbt_test_questions;
create policy "test question authorized read" on public.schoolpro_cbt_test_questions for select to authenticated
using (exists(select 1 from public.schoolpro_cbt_tests t where t.id=schoolpro_cbt_test_questions.test_id
 and private.schoolpro_module_allowed(t.school_id,'cbt') and public.schoolpro_can_author_cbt(t.school_id)));
drop policy if exists "test question managers write" on public.schoolpro_cbt_test_questions;
create policy "test question authors write" on public.schoolpro_cbt_test_questions for all to authenticated
using (exists(select 1 from public.schoolpro_cbt_tests t where t.id=schoolpro_cbt_test_questions.test_id
 and private.schoolpro_module_allowed(t.school_id,'cbt') and public.schoolpro_can_author_cbt(t.school_id)))
with check (exists(select 1 from public.schoolpro_cbt_tests t where t.id=schoolpro_cbt_test_questions.test_id
 and private.schoolpro_module_allowed(t.school_id,'cbt') and public.schoolpro_can_author_cbt(t.school_id)));

-- Do not expose draft/unpublished test metadata to generic school members.
drop policy if exists "school members read cbt tests" on public.schoolpro_cbt_tests;

-- Authors may see CBT test containers needed for question composition.
create policy "cbt authors read tests" on public.schoolpro_cbt_tests
for select to authenticated
using (
 private.schoolpro_module_allowed(school_id,'cbt')
 and public.schoolpro_can_author_cbt(school_id)
);

-- Authors can create drafts only.
create policy "cbt authors create drafts" on public.schoolpro_cbt_tests
for insert to authenticated
with check (
 status='draft'
 and private.schoolpro_module_allowed(school_id,'cbt')
 and public.schoolpro_can_author_cbt(school_id)
);

-- Authors can edit only rows that are drafts, and the resulting row must remain draft.
create policy "cbt authors edit drafts" on public.schoolpro_cbt_tests
for update to authenticated
using (
 status='draft'
 and private.schoolpro_module_allowed(school_id,'cbt')
 and public.schoolpro_can_author_cbt(school_id)
)
with check (
 status='draft'
 and private.schoolpro_module_allowed(school_id,'cbt')
 and public.schoolpro_can_author_cbt(school_id)
);

-- Authors may delete drafts; published/closed lifecycle remains exam-control only.
create policy "cbt authors delete drafts" on public.schoolpro_cbt_tests
for delete to authenticated
using (
 status='draft'
 and private.schoolpro_module_allowed(school_id,'cbt')
 and public.schoolpro_can_author_cbt(school_id)
);

-- Existing cbt managers manage tests policy remains and permits controlled publication/lifecycle.

create or replace function public.mark_schoolpro_cbt_theory(
 p_attempt uuid,p_question uuid,p_marks numeric,p_feedback text default null
) returns jsonb
language plpgsql security definer set search_path='' as $$
declare a public.schoolpro_cbt_attempts; t public.schoolpro_cbt_tests; q public.schoolpro_question_bank; v_score numeric;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 select * into a from public.schoolpro_cbt_attempts where id=p_attempt for update;
 if a.id is null then raise exception 'Attempt not found'; end if;
 select * into t from public.schoolpro_cbt_tests where id=a.test_id;
 if t.id is null or not private.schoolpro_module_allowed(t.school_id,'cbt') or not public.schoolpro_can_manage_cbt(t.school_id) then raise exception 'Not authorized'; end if;
 if a.status<>'submitted' then raise exception 'Attempt must be submitted before theory marking'; end if;
 select q0.* into q from public.schoolpro_question_bank q0
 join public.schoolpro_cbt_test_questions tq on tq.question_id=q0.id
 where tq.test_id=a.test_id and q0.id=p_question and q0.question_type='theory';
 if q.id is null then raise exception 'Theory question is not assigned to this test'; end if;
 if p_marks is null or p_marks<0 or p_marks>q.marks then raise exception 'Marks must be between 0 and %',q.marks; end if;
 update public.schoolpro_cbt_answers
 set marks_awarded=p_marks,feedback=p_feedback,marked_by=auth.uid(),marked_at=now(),is_correct=null
 where attempt_id=a.id and question_id=q.id;
 if not found then raise exception 'No submitted answer exists for this theory question'; end if;
 select coalesce(sum(ans.marks_awarded),0) into v_score
 from public.schoolpro_cbt_answers ans
 join public.schoolpro_cbt_test_questions tq on tq.question_id=ans.question_id and tq.test_id=a.test_id
 where ans.attempt_id=a.id;
 update public.schoolpro_cbt_attempts set score=v_score where id=a.id;
 return jsonb_build_object('attempt_id',a.id,'question_id',q.id,'marks_awarded',p_marks,'score',v_score,'marked_by',auth.uid());
end $$;
revoke all on function public.mark_schoolpro_cbt_theory(uuid,uuid,numeric,text) from public,anon;
grant execute on function public.mark_schoolpro_cbt_theory(uuid,uuid,numeric,text) to authenticated,service_role;

drop policy if exists "cbt answer staff manage" on public.schoolpro_cbt_answers;
create policy "cbt answer staff read" on public.schoolpro_cbt_answers for select to authenticated
