create or replace function public.get_candidate_cbt(p_token uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare a public.schoolpro_candidate_cbt_attempts;t public.schoolpro_cbt_tests;qs jsonb;saved jsonb;dur int;deadline timestamptz;
begin
 if p_token is null then raise exception 'Invalid examination link'; end if;
 select * into a from public.schoolpro_candidate_cbt_attempts where access_token=p_token for update;
 if a.id is null then raise exception 'Invalid examination link'; end if;
 if a.status='submitted' then raise exception 'Examination already submitted'; end if;
 if a.expires_at is not null and now()>a.expires_at then raise exception 'Examination link expired'; end if;
 select * into t from public.schoolpro_cbt_tests where id=a.test_id;
 if t.id is null or t.status<>'published' then raise exception 'Examination is not available'; end if;
 if t.opens_at is not null and now()<t.opens_at then raise exception 'Examination has not opened'; end if;
 if t.closes_at is not null and now()>t.closes_at then raise exception 'Examination has closed'; end if;
 dur:=greatest(coalesce(a.duration_minutes,t.duration_minutes,60),1);
 if a.started_at is null then
   update public.schoolpro_candidate_cbt_attempts set started_at=now(),status='in_progress' where id=a.id returning * into a;
 end if;
 deadline:=least(a.started_at+make_interval(mins=>dur),coalesce(a.expires_at,'infinity'::timestamptz),coalesce(t.closes_at,'infinity'::timestamptz));
 if now()>deadline then raise exception 'Examination time expired'; end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'question_type',q.question_type,'question_text',q.question_text,'options',q.options,'marks',q.marks) order by tq.position),'[]'::jsonb)
 into qs from public.schoolpro_cbt_test_questions tq join public.schoolpro_question_bank q on q.id=tq.question_id where tq.test_id=t.id;
 select coalesce(jsonb_object_agg(ans.question_id::text,ans.answer),'{}'::jsonb) into saved
 from public.schoolpro_candidate_cbt_answers ans where ans.attempt_id=a.id;
 return jsonb_build_object('attempt_id',a.id,'title',t.title,'instructions',t.instructions,'duration_minutes',dur,'started_at',a.started_at,'expires_at',deadline,'questions',qs,'saved_answers',saved);
end $$;

