-- Candidate CBT submission must not publish a partial objective subtotal as final entrance score
-- when the assigned test contains theory questions.
create or replace function public.submit_candidate_cbt(p_token uuid)
returns numeric language plpgsql security definer set search_path='' as $$
declare a public.schoolpro_candidate_cbt_attempts;t public.schoolpro_cbt_tests;dur int;s numeric;deadline timestamptz;v_theory int;
begin
 if p_token is null then raise exception 'Invalid examination attempt'; end if;
 select * into a from public.schoolpro_candidate_cbt_attempts where access_token=p_token for update;
 if a.id is null then raise exception 'Invalid examination attempt'; end if;
 if a.status='submitted' then return coalesce(a.score,0); end if;
 if a.status<>'in_progress' then raise exception 'Examination is not active'; end if;
 select * into t from public.schoolpro_cbt_tests where id=a.test_id;
 if t.id is null or t.status<>'published' then raise exception 'Examination is not available'; end if;
 dur:=greatest(coalesce(a.duration_minutes,t.duration_minutes,60),1);
 if a.started_at is null then raise exception 'Examination has not started'; end if;
 deadline:=least(a.started_at+make_interval(mins=>dur),coalesce(a.expires_at,'infinity'::timestamptz),coalesce(t.closes_at,'infinity'::timestamptz));
 if now()>deadline then raise exception 'Examination time expired'; end if;

 update public.schoolpro_candidate_cbt_answers ans
 set is_correct=(lower(trim(coalesce(ans.answer,'')))=lower(trim(coalesce(q.correct_answer,'')))),
 marks_awarded=case when lower(trim(coalesce(ans.answer,'')))=lower(trim(coalesce(q.correct_answer,''))) then q.marks else 0 end
 from public.schoolpro_question_bank q
 where ans.attempt_id=a.id and ans.question_id=q.id and q.question_type in('objective','true_false')
 and exists(select 1 from public.schoolpro_cbt_test_questions tq where tq.test_id=a.test_id and tq.question_id=q.id);

 select coalesce(sum(ans.marks_awarded),0) into s
 from public.schoolpro_candidate_cbt_answers ans
 where ans.attempt_id=a.id and exists(select 1 from public.schoolpro_cbt_test_questions tq where tq.test_id=a.test_id and tq.question_id=ans.question_id);

 select count(*) into v_theory from public.schoolpro_cbt_test_questions tq
 join public.schoolpro_question_bank q on q.id=tq.question_id
 where tq.test_id=a.test_id and q.question_type='theory';

 update public.schoolpro_candidate_cbt_attempts
 set status='submitted',submitted_at=now(),score=s,last_saved_at=now() where id=a.id;

 if v_theory=0 then
   update public.schoolpro_admissions set entrance_score=s where id=a.application_id;
 end if;
 return s;
end $$;

