declare ca public.schoolpro_candidate_cbt_attempts; ad public.schoolpro_admissions;
q public.schoolpro_question_bank; v_score numeric; v_unmarked int;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 select * into ca from public.schoolpro_candidate_cbt_attempts where id=p_attempt for update;
 if ca.id is null or ca.status<>'submitted' then raise exception 'Submitted candidate attempt not found'; end if;
 select * into ad from public.schoolpro_admissions where id=ca.application_id;
 if ad.id is null or not private.schoolpro_module_allowed(ad.school_id,'admissions')
