  'proprietor'::public.school_member_role,'administrator'::public.school_member_role,
  'registrar'::public.school_member_role,'admissions_officer'::public.school_member_role,
  'exam_officer'::public.school_member_role,'head_teacher'::public.school_member_role,
  'vice_principal'::public.school_member_role]) then raise exception 'Not authorized'; end if;

 select q0.* into q from public.schoolpro_question_bank q0
 join public.schoolpro_cbt_test_questions tq on tq.question_id=q0.id
 where tq.test_id=ca.test_id and q0.id=p_question and q0.question_type='theory';
 if q.id is null then raise exception 'Theory question is not assigned to this examination'; end if;
 if p_marks is null or p_marks<0 or p_marks>q.marks then raise exception 'Marks must be between 0 and %',q.marks; end if;

 update public.schoolpro_candidate_cbt_answers
 set marks_awarded=p_marks,is_correct=null,feedback=p_feedback,marked_by=auth.uid(),marked_at=now()
 where attempt_id=ca.id and question_id=q.id;
 if not found then raise exception 'No submitted answer exists for this theory question'; end if;

 select coalesce(sum(ans.marks_awarded),0) into v_score
 from public.schoolpro_candidate_cbt_answers ans
 where ans.attempt_id=ca.id
 and exists(select 1 from public.schoolpro_cbt_test_questions tq where tq.test_id=ca.test_id and tq.question_id=ans.question_id);

 select count(*) into v_unmarked
 from public.schoolpro_candidate_cbt_answers ans
 join public.schoolpro_question_bank qq on qq.id=ans.question_id
 where ans.attempt_id=ca.id and qq.question_type='theory' and ans.marked_at is null
 and exists(select 1 from public.schoolpro_cbt_test_questions tq where tq.test_id=ca.test_id and tq.question_id=ans.question_id);

 update public.schoolpro_candidate_cbt_attempts set score=v_score where id=ca.id;
 if v_unmarked=0 then
   update public.schoolpro_admissions set entrance_score=v_score where id=ca.application_id;
 end if;
 return jsonb_build_object('attempt_id',ca.id,'question_id',q.id,'marks_awarded',p_marks,
 'score',v_score,'theory_unmarked',v_unmarked,'finalized',v_unmarked=0);
end $$;

