create or replace function private.validate_schoolpro_assignment_target()
returns trigger language plpgsql security definer set search_path='' as $$
declare v_member uuid;
begin
 if not exists(select 1 from public.schoolpro_classes c where c.id=new.class_id and c.school_id=new.school_id)
 then raise exception 'Class does not belong to assignment school';end if;
 if not exists(select 1 from public.schoolpro_subjects s where s.id=new.subject_id and s.school_id=new.school_id)
 then raise exception 'Subject does not belong to assignment school';end if;
 if auth.uid() is not null
 and not private.has_school_access(new.school_id,array['proprietor'::public.school_member_role,'administrator'::public.school_member_role,'head_teacher'::public.school_member_role,'vice_principal'::public.school_member_role]) then
   select m.id into v_member from public.schoolpro_members m
   where m.school_id=new.school_id and m.user_id=auth.uid()
   and m.role in('teacher','class_teacher') limit 1;
   if v_member is null or not exists(
    select 1 from public.schoolpro_subject_assignments sa
    where sa.school_id=new.school_id and sa.class_id=new.class_id
    and sa.subject_id=new.subject_id and sa.teacher_member_id=v_member
   ) then raise exception 'Teacher is not assigned to this class and subject';end if;
 end if;
 return new;
end $$;
