create or replace function public.schoolpro_printable_result(p_student uuid,p_term text,p_session text)
returns setof public.schoolpro_results language plpgsql stable security definer set search_path='' as $$
declare s public.schoolpro_students;v_allowed boolean;
begin
 if auth.uid() is null then raise exception 'Authentication required';end if;
 select * into s from public.schoolpro_students where id=p_student and status='active';
 if s.id is null then raise exception 'Student not found';end if;
 if not(
  private.is_admin(array['super_admin'::public.user_role])
  or private.has_school_access(s.school_id,array['proprietor'::public.school_member_role,'administrator'::public.school_member_role,'exam_officer'::public.school_member_role,'head_teacher'::public.school_member_role,'vice_principal'::public.school_member_role])
  or exists(select 1 from public.schoolpro_subject_assignments sa join public.schoolpro_members m on m.id=sa.teacher_member_id where sa.school_id=s.school_id and sa.class_id=s.class_id and sa.session=trim(p_session) and m.user_id=auth.uid() and m.role in('teacher'::public.school_member_role,'class_teacher'::public.school_member_role))
  or s.user_id=auth.uid()
  or exists(select 1 from public.schoolpro_guardian_links g where g.student_id=s.id and g.guardian_user_id=auth.uid() and g.status='active')
 ) then raise exception 'Not authorized for this printable result';end if;
 select a.allowed into v_allowed from public.schoolpro_result_access(p_student,trim(p_term),trim(p_session)) a limit 1;
 if coalesce(v_allowed,false)=false then raise exception 'Result output is not available';end if;
 return query select r.* from public.schoolpro_results r where r.student_id=p_student and r.term=trim(p_term) and r.session=trim(p_session) and r.status='published' and r.locked=true order by r.created_at;
end $$;
