as $$
declare
  v_user uuid := auth.uid();
  v_assignment public.academy_assignments;
  v_enrollment public.academy_enrollments;
  v_id uuid;
begin
  if v_user is null then raise exception 'Authentication required'; end if;

  select * into v_assignment
  from public.academy_assignments
  where id = p_assignment_id
  for share;

  if v_assignment.id is null or not v_assignment.is_published then
    raise exception 'Published assignment not found';
  end if;
  if v_assignment.due_at is not null and now() > v_assignment.due_at then
    raise exception 'Assignment deadline has passed';
  end if;
  if nullif(trim(coalesce(p_submission_text,'')),'') is null
     and nullif(trim(coalesce(p_submission_url,'')),'') is null then
    raise exception 'Submission text or URL is required';
  end if;

  select * into v_enrollment
  from public.academy_enrollments
  where user_id = v_user
    and course_id = v_assignment.course_id
    and status = 'active'
  order by enrolled_at desc
  limit 1
  for share;

  if v_enrollment.id is null then
    raise exception 'An active course enrolment is required';
  end if;

  if exists (
    select 1 from public.academy_assignment_submissions
    where assignment_id=p_assignment_id and enrollment_id=v_enrollment.id
  ) then
    raise exception 'This assignment has already been submitted';
  end if;

  insert into public.academy_assignment_submissions(
    assignment_id,enrollment_id,submission_url,submission_text,status
  ) values (
    p_assignment_id,v_enrollment.id,
    nullif(trim(coalesce(p_submission_url,'')),''),
    nullif(trim(coalesce(p_submission_text,'')),''),
    'submitted'
  ) returning id into v_id;

  return v_id;
end
$$;

revoke all on function public.submit_academy_assignment(uuid,text,text) from public, anon;
grant execute on function public.submit_academy_assignment(uuid,text,text) to authenticated, service_role;

drop policy if exists "academy learners create own submissions" on public.academy_assignment_submissions;

drop policy if exists "academy learner reads issued certificate output" on storage.objects;
create policy "academy learner reads issued certificate output"
on storage.objects for select to authenticated
using (
  bucket_id='schoolpro-document-templates'
  and exists (
    select 1
    from public.academy_certificates c
    join public.academy_enrollments e on e.id=c.enrollment_id
    where c.output_storage_path=storage.objects.name
      and c.status='issued'
      and e.user_id=auth.uid()
  )
);

create or replace function private.business_order_payment_guard() returns trigger language plpgsql set search_path='' as $$
begin
 if new.status in ('paid','in_progress','completed','delivered') and new.status is distinct from old.status
    and not exists(select 1 from public.business_invoices i where i.order_id=new.id and i.status='paid' and i.amount_paid=i.amount and i.amount>0)
 then raise exception 'Verified invoice payment is required before fulfilment'; end if;
 return new;
end $$;

drop policy if exists "business_quote_customer_response" on public.business_quotes;

create or replace function public.respond_business_quote(p_quote uuid,p_response text) returns void
language plpgsql security definer set search_path='' as $$
declare q public.business_quotes%rowtype;o public.business_orders%rowtype;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 if p_response not in ('accepted','revision_requested','rejected') then raise exception 'Invalid quote response'; end if;
 select * into q from public.business_quotes where id=p_quote for update;
 if q.id is null or q.status<>'issued' then raise exception 'Issued quote unavailable'; end if;
 select * into o from public.business_orders where id=q.order_id for update;
 if o.user_id is distinct from auth.uid() then raise exception 'Quote does not belong to this customer'; end if;
 if q.valid_until is not null and q.valid_until<current_date then raise exception 'Quote has expired'; end if;
 update public.business_quotes set status=p_response,updated_at=now() where id=q.id;
 update public.business_orders set status=case p_response when 'accepted' then 'quoted' when 'revision_requested' then 'reviewing' else 'cancelled' end,updated_at=now() where id=o.id;
end $$;
revoke all on function public.respond_business_quote(uuid,text) from public,anon;
grant execute on function public.respond_business_quote(uuid,text) to authenticated,service_role;
